"""Small, transparent TR/EN query rules; these do not infer unseen facts."""

from dataclasses import dataclass, replace
from enum import Enum
import math
import re
import unicodedata

from virvision.scene.models import DetectedObject, VisualScene


class QueryCategory(str, Enum):
    COUNT = "count"
    OCR = "ocr"
    OBJECT_EXISTENCE = "object_existence"
    ATTRIBUTE = "attribute"
    COLOR = "color"
    POSITION = "position"
    RELATION = "relation"
    ACTION = "action"
    SCENE = "scene"
    COMPARISON = "comparison"
    GENERAL_DESCRIPTION = "general_description"


def normalize(text: str) -> str:
    text = text.casefold().replace("ı", "i")
    return "".join(c for c in unicodedata.normalize("NFKD", text) if not unicodedata.combining(c))


ALIASES = {
    "person": (
        "person",
        "people",
        "man",
        "woman",
        "boy",
        "girl",
        "kisi",
        "insan",
        "adam",
        "kadin",
        "cocuk",
    ),
    "car": ("car", "cars", "araba", "otomobil"),
    "bicycle": ("bicycle", "bike", "bisiklet"),
    "phone": ("phone", "telefon"),
    "bag": ("bag", "canta"),
    "cat": ("cat", "kedi"),
    "dog": ("dog", "kopek"),
    "hat": ("hat", "sapka"),
    "sign": ("sign", "tabela", "levha"),
    "cup": ("cup", "mug", "bardak", "fincan"),
}
COLORS = {
    "red": ("red", "kirmizi"),
    "blue": ("blue", "mavi"),
    "green": ("green", "yesil"),
    "white": ("white", "beyaz"),
    "black": ("black", "siyah"),
    "yellow": ("yellow", "sari"),
}
PREDICATES = {
    "holding": ("holding", "holds", "hold", "tutuyor", "elinde"),
    "carrying": ("carrying", "carries", "tasiyor"),
    "left_of": ("left", "sol", "solunda"),
    "right_of": ("right", "sag", "saginda"),
    "above": ("above", "ust", "ustunde"),
    "below": ("below", "alt", "altinda"),
    "inside": ("inside", "icinde"),
    "near": ("near", "yaninda", "next to"),
    "riding": ("riding", "biniyor"),
}
TR_STEMS = {
    "kisi",
    "insan",
    "adam",
    "kadin",
    "cocuk",
    "araba",
    "otomobil",
    "bisiklet",
    "telefon",
    "canta",
    "kedi",
    "kopek",
    "sapka",
    "tabela",
    "levha",
    "bardak",
    "fincan",
    "kirmizi",
    "mavi",
    "yesil",
    "beyaz",
    "siyah",
    "sari",
    "yazi",
    "metin",
    "renk",
    "sol",
    "sag",
    "ust",
    "alt",
    "ozellik",
    "sekil",
    "mekan",
    "ortam",
}
TR_SUFFIX = r"(?:lar|ler)?(?:in|nin|un|nun|i|yi|u|yu|a|ya|e|ye|da|de|ta|te|dan|den|tan|ten|la|le|yla|yle|inda|inde|unda|unde|indaki|indeki|undaki|undeki)?"


def _contains(text: str, phrases: tuple[str, ...]) -> bool:
    # Bounded suffixes prevent English 'many'/'carpet' matching 'man'/'car'.
    return any(
        re.search(
            r"(?<!\w)" + re.escape(p) + (TR_SUFFIX if p in TR_STEMS else r"(?:s|es)?") + r"(?!\w)",
            text,
        )
        for p in phrases
    )


@dataclass(frozen=True)
class QueryIntent:
    query: str | None
    categories: tuple[QueryCategory, ...]
    targets: tuple[str, ...]
    colors: tuple[str, ...]
    predicates: tuple[str, ...] = ()

    @property
    def spatial(self) -> bool:
        return any(
            c in self.categories
            for c in (QueryCategory.POSITION, QueryCategory.RELATION, QueryCategory.ACTION)
        )


def analyze_query(query: str | None) -> QueryIntent:
    if not query or not query.strip():
        return QueryIntent(None, (QueryCategory.GENERAL_DESCRIPTION,), (), ())
    text = normalize(query)
    categories = []
    rules = (
        (QueryCategory.COUNT, ("kac", "how many", "count", "number of")),
        (
            QueryCategory.OCR,
            ("yazi", "yaziyor", "oku", "metin", "read", "text", "say", "says", "tabela"),
        ),
        (QueryCategory.OBJECT_EXISTENCE, ("var mi", "is there", "are there", "exists")),
        (QueryCategory.COLOR, ("renk", "rengi", "color", "colour")),
        (
            QueryCategory.POSITION,
            (
                "sol",
                "sag",
                "ust",
                "alt",
                "nerede",
                "left",
                "right",
                "above",
                "below",
                "where",
                "inside",
            ),
        ),
        (
            QueryCategory.RELATION,
            (
                "yaninda",
                "arasinda",
                "next to",
                "between",
                "holding",
                "tutuyor",
                "elinde",
                "carrying",
            ),
        ),
        (QueryCategory.ACTION, ("yapiyor", "doing", "riding", "biniyor")),
        (
            QueryCategory.COMPARISON,
            ("buyuk", "kucuk", "bigger", "smaller", "compare", "karsilastir"),
        ),
        (QueryCategory.SCENE, ("mekan", "ortam", "scene", "indoor", "outdoor")),
        (QueryCategory.ATTRIBUTE, ("giy", "wear", "ozellik", "attribute", "shape", "sekil")),
    )
    for category, phrases in rules:
        if _contains(text, phrases):
            categories.append(category)
    targets = tuple(k for k, aliases in ALIASES.items() if _contains(text, aliases))
    colors = tuple(k for k, aliases in COLORS.items() if _contains(text, aliases))
    predicates = tuple(k for k, aliases in PREDICATES.items() if _contains(text, aliases))
    if colors and QueryCategory.COLOR not in categories:
        categories.append(QueryCategory.COLOR)
    if predicates and not any(
        c in categories
        for c in (QueryCategory.RELATION, QueryCategory.POSITION, QueryCategory.ACTION)
    ):
        categories.append(QueryCategory.RELATION)
    return QueryIntent(
        query, tuple(categories or [QueryCategory.GENERAL_DESCRIPTION]), targets, colors, predicates
    )


def object_relevance(obj: DetectedObject, intent: QueryIntent) -> float:
    if intent.query is None:
        return 0.5
    label = normalize(obj.label)
    if intent.targets:
        matched = any(
            label == target or _contains(label, ALIASES[target]) for target in intent.targets
        )
        relevance = 0.9 if matched else 0.05
    else:
        query_words = set(re.findall(r"\w+", normalize(intent.query)))
        relevance = 0.9 if label in query_words else 0.45
    if intent.colors:
        values = " ".join(normalize(a.value) for a in obj.attributes)
        if any(_contains(values, COLORS[color]) for color in intent.colors):
            relevance = min(1.0, relevance + 0.1)
    return relevance


@dataclass(frozen=True)
class ConfidenceThresholds:
    object_min: float = 0.35
    ocr_min: float = 0.50
    relation_min: float = 0.60
    attribute_min: float = 0.35
    caption_min: float = 0.35

    def __post_init__(self) -> None:
        for name, value in vars(self).items():
            if (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(value)
                or not 0 <= value <= 1
            ):
                raise ValueError(f"{name} must be finite and within [0,1]")


def filter_confidence(scene: VisualScene, thresholds: ConfidenceThresholds) -> VisualScene:
    objects = tuple(
        replace(
            o, attributes=tuple(a for a in o.attributes if a.confidence >= thresholds.attribute_min)
        )
        for o in scene.objects
        if o.confidence >= thresholds.object_min
    )
    ids = {o.id for o in objects}
    return replace(
        scene,
        objects=objects,
        texts=tuple(t for t in scene.texts if t.confidence >= thresholds.ocr_min),
        relations=tuple(
            r
            for r in scene.relations
            if r.confidence >= thresholds.relation_min and r.source in ids and r.target in ids
        ),
        caption=scene.caption
        if scene.caption and scene.caption.confidence >= thresholds.caption_min
        else None,
        tags=tuple(t for t in scene.tags if t.confidence >= thresholds.caption_min),
    )
